1. Send a GET request to the given URL and handle any request errors by returning an empty list.
2. Parse the HTML content with BeautifulSoup and locate all <script> tags.
3. For each script tag, extract its text content and attempt to parse it as a Python dictionary using ast.literal_eval.
4. Collect all successfully parsed dictionaries into a list.
5. Return the list of dictionaries, or an empty list if none were found or if any error occurred.

### code
import ast
import requests
from bs4 import BeautifulSoup
def task_func(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
    except Exception:
        return []
    try:
        soup = BeautifulSoup(response.text, 'html.parser')
        scripts = soup.find_all('script')
    except Exception:
        return []
    result = []
    for script in scripts:
        text = script.string
        if text is None:
            continue
        try:
            parsed = ast.literal_eval(text.strip())
            if isinstance(parsed, dict):
                result.append(parsed)
        except Exception:
            continue
    return result

